// ⓪ ENTRADA · mantenimiento diario del portero · CC#2 · 2026-10-10 · + «completar despertar» (CC-CEREBRO · 15-oct).
//  · por HORARIO: corre de verdad (dry_run=false), para todos los clientes activos.
//  · a mano (webhook con llave de despacho): `dry_run` BOOLEANO OBLIGATORIO; `client_id` (uuid) opcional limita el alcance.
//  · completar despertar (webhook con llave interna): lo llama el ALTA para UN cliente tras el despertar; exige `client_id` uuid y `pedir_ahora === true`. Misma cadena que la diaria.
// 🔴 Sin llave, o sin `dry_run` booleano en la entrada a mano, el flujo SE DETIENE aquí: no se lee ni se escribe nada.
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
let d = null
try { d = $('Webhook · completar despertar (llave interna)').first() } catch (e) { d = null }
let w = null
try { w = $('Webhook · a mano (con llave)').first() } catch (e) { w = null }
let u = null
try { u = $('Webhook · un cliente (llave interna)').first() } catch (e) { u = null }
const base = { workflow_id: String($workflow.id), workflow_execution_id: String($execution.id) }
if (u) {
  const h = u.json || {}
  const esperada = String($env.INTERNAL_API_KEY || '')
  const recibida = String((h.headers || {})['x-api-key'] || '')
  if (!esperada || recibida !== esperada) throw new Error('UN_CLIENTE_SIN_LLAVE · falta o no coincide x-api-key · se DETIENE')
  const b = h.body || {}
  if (typeof b.client_id !== 'string' || !UUID.test(b.client_id)) throw new Error('UN_CLIENTE_INVALIDO · `client_id` es obligatorio y debe ser un uuid · se DETIENE')
  return [{ json: { ...base, via: 'cliente', dry_run: false, client_id: b.client_id, reintento: b.reintento === true } }]
}
if (d) {
  const h = d.json || {}
  const esperada = String($env.INTERNAL_API_KEY || '')
  const recibida = String((h.headers || {})['x-api-key'] || '')
  if (!esperada || recibida !== esperada) throw new Error('DESPERTAR_SIN_LLAVE · falta o no coincide x-api-key (o INTERNAL_API_KEY no está configurada) · se DETIENE')
  const b = h.body || {}
  if (typeof b.client_id !== 'string' || !UUID.test(b.client_id)) throw new Error('DESPERTAR_CLIENTE_INVALIDO · `client_id` es obligatorio y debe ser un uuid · se DETIENE')
  if (b.pedir_ahora !== true) return []
  return [{ json: { ...base, via: 'despertar', dry_run: false, client_id: b.client_id } }]
}
if (!w) return [{ json: { ...base, via: 'horario', dry_run: false, client_id: null } }]
const h = w.json || {}
const esperada = String($env.SALA_DISPATCH_KEY || '')
const recibida = String((h.headers || {})['x-sala-dispatch-key'] || '')
if (!esperada || recibida !== esperada) throw new Error('DIARIO_SIN_LLAVE · falta o no coincide x-sala-dispatch-key (o SALA_DISPATCH_KEY no está configurada) · se DETIENE')
const b = h.body || {}
if (typeof b.dry_run !== 'boolean') throw new Error('DIARIO_DRY_RUN_OBLIGATORIO · `dry_run` es obligatorio y debe ser true o false · se DETIENE')
if (b.client_id !== undefined && (typeof b.client_id !== 'string' || !UUID.test(b.client_id))) throw new Error('DIARIO_CLIENTE_INVALIDO · `client_id` debe ser un uuid · se DETIENE')
return [{ json: { ...base, via: 'a mano', dry_run: b.dry_run, client_id: b.client_id || null } }]

// ① SEPARAR EL PLAN EN UN ELEMENTO POR CLIENTE. Si el plan falló, se DICE (un fallo nunca se lee como «no hay clientes»).
const e = $('⓪ Entrada').first().json
const r = $input.first().json || {}
const p = r.body ? r.body : r
if (!p || p.error || !Array.isArray(p.clientes)) return [{ json: { ...e, cliente: null, falla: 'El plan falló: ' + String((p && (p.error || p.detalle)) || 'sin respuesta') + ' ' + String((p && p.detalle) || '') } }]
if (!p.clientes.length) return [{ json: { ...e, cliente: null, falla: null, sin_clientes: true, excluidos: p.excluidos || [] } }]
return p.clientes.map((c) => ({ json: { ...e, cliente: c.client_id, nombre: c.nombre, acciones: (c.plan && c.plan.hacer) || [], omitidas: (c.plan && c.plan.omitidas) || [], no_cubiertas: (c.plan && c.plan.no_cubiertas) || [], gastado_hoy_usd: c.gastado_hoy_usd, falla: null } }))

// ② LA AMPLIACIÓN (paso 1, lo que el flujo de la mañana NO cubre) · ejecuta SOLO lo que la ruta `plan` dejó en `acciones` de CADA cliente (ya recortado al tope de US$ 1,00 por cliente y día).
// 🔴 Con `dry_run` NO llama a nadie. 🔴 Una llamada al Servicio por acción, SIN reintento (cada una paga). 🔴 Dos fallas seguidas por cliente ⇒ para a ese cliente. Este nodo NO lee ninguna tabla: lo decide la ruta.
// El Servicio guarda lo crudo en `apify_raw` (destino `respuesta`); lo que cuesta se mide con la API de Apify y se informa a `correr`, que lo compara con el tope.
// Procesa TODOS los elementos (uno por cliente), en orden, y devuelve uno por cliente.
const N8N = 'https://n8n-production-72be.up.railway.app'
const http = async (o) => this.helpers.httpRequest({ json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 140000, ...o }).catch((err) => ({ statusCode: 0, body: { error: 'sin respuesta: ' + String((err && err.message) || err).slice(0, 140) } }))
const T0 = Date.now() // presupuesto de tiempo: n8n corta la tarea de código a los 120 s
const RESTA_MS = () => Math.max(5000, 112000 - (Date.now() - T0))
const ES_ULTIMA = true
const salidas = []
for (const item of $input.all()) {
  const e = item.json
  const salida = { ...e, ampliacion: e.ampliacion ? { ...e.ampliacion } : { hecho: false, llamadas: [], gasto_usd: 0, parado: null } }
  delete salida.acciones_pendientes
  if (e.falla || !e.cliente) { salidas.push({ json: salida }); continue }
  if (e.dry_run === true) { salida.ampliacion.nota = 'dry_run: no se llamó a ningún proveedor'; salidas.push({ json: salida }); continue }
  let seguidasConFalla = e.ampliacion && e.ampliacion.seguidas_con_falla ? e.ampliacion.seguidas_con_falla : 0
  const pendientes = []
  const lista = Array.isArray(e.acciones_pendientes) ? e.acciones_pendientes : e.acciones || []
  for (const a of lista) {
    if (salida.ampliacion.parado) continue // dos fallas seguidas: se declara en parado, no se sigue
    if (Date.now() - T0 > 60000) { pendientes.push(a); continue } // no cupo en este nodo: pasa al siguiente
    const t0 = Date.now()
    const r = await http({ timeout: RESTA_MS(), url: N8N + '/webhook/apify-service-workflow', method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: { client_id: e.cliente, apify_function: a.funcion, params: a.params, destination: 'respuesta', dry_run: false, origen: 'portero', metadata: { ...(a.metadata || {}), calling_workflow_id: e.workflow_id } } })
    const b = r.body && typeof r.body === 'object' ? r.body : {}
    const ll = { fuente: a.fuente, funcion: a.funcion, hecho: r.statusCode === 200 && b.ok === true, http: r.statusCode, ms: Date.now() - t0, apify_run_id: b.apify_run_id || null, usd_max: a.usd_max, medido: a.medido }
    if (!ll.hecho) ll.error = String(b.error || b.message || b.validation_errors || '').slice(0, 160)
    let costo = typeof a.usd_max === 'number' ? a.usd_max : 0 // sin dato real, se cuenta el MÁXIMO (nunca 0 para decir «no sé»)
    if (ll.apify_run_id && $env.APIFY_API_TOKEN) {
      const u = await http({ timeout: Math.min(15000, RESTA_MS()), url: 'https://api.apify.com/v2/actor-runs/' + ll.apify_run_id, method: 'GET', headers: { Authorization: 'Bearer ' + $env.APIFY_API_TOKEN } })
      const d = u.body && u.body.data
      if (d && d.usageTotalUsd !== undefined) { ll.costo_real_usd = Number(d.usageTotalUsd); costo = ll.costo_real_usd }
    }
    ll.costo_contado_usd = costo
    salida.ampliacion.gasto_usd = Number((salida.ampliacion.gasto_usd + costo).toFixed(6))
    salida.ampliacion.llamadas.push(ll)
    seguidasConFalla = ll.hecho ? 0 : seguidasConFalla + 1
    if (seguidasConFalla >= 2) { salida.ampliacion.parado = 'dos_fallas_seguidas'; break }
  }
  salida.ampliacion.seguidas_con_falla = seguidasConFalla
  if (ES_ULTIMA) {
    salida.ampliacion.omitidas_por_tiempo = pendientes.map((a) => a.fuente + ': ' + a.funcion) // se DICE lo que no cupo
    delete salida.ampliacion.seguidas_con_falla
  } else salida.acciones_pendientes = pendientes
  salida.ampliacion.hecho = salida.ampliacion.llamadas.length > 0 && salida.ampliacion.llamadas.every((l) => l.hecho) && pendientes.length === 0
  salidas.push({ json: salida })
}
return salidas

// ⑤ CIERRE · una línea por cliente: qué pidió el portero, qué leyó, qué archivó (suma / reemplaza / nada / duda), qué quedó en la biblioteca y qué costó. Un error se DICE.
const clientes = $input.all().map((i) => i.json).map((p) => {
  const a = p.alimentada || {}
  const res = (a.plan && a.plan.resumen) || {}
  const q = p.puente_final || {}
  return {
    cliente: p.cliente || null,
    plan_fallo: p.falla || null,
    portero: p.portero || null,
    ampliacion: p.ampliacion ? { hecho: p.ampliacion.hecho, gasto_usd: p.ampliacion.gasto_usd, parado: p.ampliacion.parado, llamadas: (p.ampliacion.llamadas || []).length } : null,
    articulos: p.articulos ? { hecho: p.articulos.hecho, llamadas: (p.articulos.llamadas || []).length, gasto_usd: p.articulos.gasto_usd } : null,
    tanda2: p.tanda2 ? { hecho: p.tanda2.hecho, llamadas: (p.tanda2.llamadas || []).map((l) => l.funcion), gasto_usd: p.tanda2.gasto_usd, revision: p.tanda2.revision, omitidas: (p.tanda2.omitidas || []).map((o) => o.fuente + ': ' + o.por_que) } : null,
    omitidas_por_tiempo: [].concat((p.ampliacion && p.ampliacion.omitidas_por_tiempo) || [], (p.articulos && p.articulos.omitidas_por_tiempo) || [], (p.tanda2 && p.tanda2.omitidas_por_tiempo) || []),
    alimentar: a.apagado ? 'apagado' : a.estado || (p.falla ? 'saltado' : 'sin_respuesta'),
    suma: res.suma || 0, reemplaza: res.reemplaza || 0, nada: res.nada || 0, duda: res.duda || 0, sin_confirmar: res.sin_confirmar || 0,
    modelo_usd: (a.gasto && a.gasto.modelo_usd) || 0,
    puente: { quedan: typeof q.quedan === 'number' ? q.quedan : null, vueltas: (q.vueltas || []).length, falla: q.falla || q.lectura_fallida || null },
    errores: [].concat(Array.isArray(a.errores) ? a.errores : []),
    detalle: a.detalle || a.error || null,
  }
})
const e = $('⓪ Entrada').first().json
const malo = clientes.some((c) => c.plan_fallo || c.errores.length > 0 || c.puente.falla || (typeof c.puente.quedan === 'number' && c.puente.quedan > 0) || ['con_errores', 'lectura_fallida', 'sin_respuesta'].includes(c.alimentar))
return [{ json: { fin: malo ? 'con_errores' : 'hecho', via: e.via, dry_run: e.dry_run, clientes } }]

// ① PLAN UNIFICADO · junta, por cliente, lo que el plan de hoy dijo (quién es cliente activo) con lo que dice el portero que alimenta (qué pedirle hoy a Apify: TODO diario, tope US$ 1,50).
// 🔴 Si el portero está APAGADO (PORTERO_ALIMENTAR) la ruta contesta {apagado:true}: aquí no hay acciones y el flujo no pide nada nuevo. Un fallo se DICE; nunca se lee como «no hay nada».
const base = $('① Un elemento por cliente').all().map((i) => i.json)
const resp = $input.all().map((i) => { const r = i.json || {}; return r.body ? r.body : r })
return base.map((e, k) => {
  const r = resp[k] || {}
  if (e.falla || !e.cliente) return { json: { ...e, portero: { omitido: true } } }
  if (r.apagado) return { json: { ...e, acciones: [], omitidas: [], no_cubiertas: [], portero: { apagado: true } } }
  if (r.error || !r.plan) return { json: { ...e, acciones: [], falla: 'El portero no pudo armar el plan: ' + String(r.error || r.detalle || 'sin respuesta'), portero: { error: true } } }
  return { json: { ...e, acciones: r.plan.hacer || [], omitidas: r.plan.omitidas || [], no_cubiertas: r.plan.no_cubiertas || [], gastado_hoy_usd: (r.gasto_de_hoy && r.gasto_de_hoy.total_usd) || 0,
    portero: { tope_usd: r.tope_por_cliente_usd, costo_maximo_del_plan_usd: r.plan.costo_maximo_del_plan_usd, propuestas: (r.propuestas && r.propuestas.aceptadas) || [] } } }
})

// ② bis · LEE las páginas que el portero eligió de la búsqueda de hoy (≤ 3, nunca el sitio propio ni redes). Misma regla que ②: con dry_run NO llama a nadie; una llamada por página, SIN reintento.
// El Servicio guarda SOLO calling_workflow_id como llamado_por: la tanda lleva el sufijo «#articulo» para que el portero sepa que es una página de un tercero.
const N8N = 'https://n8n-production-72be.up.railway.app'
const http = async (o) => this.helpers.httpRequest({ json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 140000, ...o }).catch((err) => ({ statusCode: 0, body: { error: 'sin respuesta: ' + String((err && err.message) || err).slice(0, 140) } }))
const T0 = Date.now() // presupuesto de tiempo: n8n corta la tarea de código a los 120 s
const RESTA_MS = () => Math.max(5000, 112000 - (Date.now() - T0))
const previos = $('② Ampliar (Servicio de Apify)').all().map((i) => i.json)
const resp = $input.all().map((i) => { const r = i.json || {}; return r.body ? r.body : r })
const salidas = []
for (let k = 0; k < previos.length; k++) {
  const e = previos[k]
  const r = resp[k] || {}
  const salida = { ...e, articulos: { hecho: false, llamadas: [], gasto_usd: 0, omitidas: r.omitidas || [] } }
  if (e.falla || !e.cliente || e.dry_run === true || r.apagado || !Array.isArray(r.acciones)) { salida.articulos.nota = e.dry_run === true ? 'dry_run: no se llamó a ningún proveedor' : 'sin páginas que leer'; salidas.push({ json: salida }); continue }
  for (const a of r.acciones) {
    if (Date.now() - T0 > 80000) { (salida.articulos.omitidas_por_tiempo = salida.articulos.omitidas_por_tiempo || []).push(a.funcion + (a.objetivo ? ' · ' + a.objetivo : '')); continue }
    const t0 = Date.now()
    const x = await http({ timeout: RESTA_MS(), url: N8N + '/webhook/apify-service-workflow', method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: { client_id: e.cliente, apify_function: a.funcion, params: a.params, destination: 'respuesta', dry_run: false, origen: 'portero_articulo', metadata: { ...(a.metadata || {}), calling_workflow_id: e.workflow_id + '#articulo' } } })
    const b = x.body && typeof x.body === 'object' ? x.body : {}
    const ok = x.statusCode === 200 && b.ok === true
    salida.articulos.llamadas.push({ funcion: a.funcion, objetivo: a.objetivo, hecho: ok, http: x.statusCode, ms: Date.now() - t0, usd_max: a.usd_max })
    salida.articulos.gasto_usd = Number((salida.articulos.gasto_usd + (typeof a.usd_max === 'number' ? a.usd_max : 0)).toFixed(6))
  }
  salida.articulos.hecho = salida.articulos.llamadas.length > 0 && salida.articulos.llamadas.every((l) => l.hecho)
  // el gasto de las páginas se suma al de la ampliación para que `correr` lo compare con el tope
  salida.ampliacion = { ...(e.ampliacion || {}), gasto_usd: Number((((e.ampliacion && e.ampliacion.gasto_usd) || 0) + salida.articulos.gasto_usd).toFixed(6)) }
  salidas.push({ json: salida })
}
return salidas

// ② ter · pide al Servicio lo que la tanda 1 hizo posible: las reseñas de la ficha CONFIRMADA de Mapas y los videos de Instagram solo si hubo publicaciones nuevas.
// Misma regla que ②: con dry_run NO llama a nadie; una llamada por acción, SIN reintento. Sufijo «#tanda2» en calling_workflow_id.
const N8N = 'https://n8n-production-72be.up.railway.app'
const http = async (o) => this.helpers.httpRequest({ json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 140000, ...o }).catch((err) => ({ statusCode: 0, body: { error: 'sin respuesta: ' + String((err && err.message) || err).slice(0, 140) } }))
const T0 = Date.now() // presupuesto de tiempo: n8n corta la tarea de código a los 120 s
const RESTA_MS = () => Math.max(5000, 112000 - (Date.now() - T0))
const previos = $('② bis Leer artículos (Servicio de Apify)').all().map((i) => i.json)
const resp = $input.all().map((i) => { const r = i.json || {}; return r.body ? r.body : r })
const salidas = []
for (let k = 0; k < previos.length; k++) {
  const e = previos[k]
  const r = resp[k] || {}
  const salida = { ...e, tanda2: { hecho: false, llamadas: [], gasto_usd: 0, omitidas: r.omitidas || [], revision: r.revision_de_publicaciones || null } }
  if (e.falla || !e.cliente || e.dry_run === true || r.apagado || !Array.isArray(r.acciones)) { salida.tanda2.nota = e.dry_run === true ? 'dry_run: no se llamó a ningún proveedor' : 'sin nada que pedir'; salidas.push({ json: salida }); continue }
  for (const a of r.acciones) {
    if (Date.now() - T0 > 80000) { (salida.tanda2.omitidas_por_tiempo = salida.tanda2.omitidas_por_tiempo || []).push(a.funcion + (a.objetivo ? ' · ' + a.objetivo : '')); continue }
    const t0 = Date.now()
    const x = await http({ timeout: RESTA_MS(), url: N8N + '/webhook/apify-service-workflow', method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: { client_id: e.cliente, apify_function: a.funcion, params: a.params, destination: 'respuesta', dry_run: false, origen: 'portero_tanda2', metadata: { ...(a.metadata || {}), calling_workflow_id: e.workflow_id + '#tanda2' } } })
    const b = x.body && typeof x.body === 'object' ? x.body : {}
    salida.tanda2.llamadas.push({ funcion: a.funcion, objetivo: a.objetivo, hecho: x.statusCode === 200 && b.ok === true, http: x.statusCode, ms: Date.now() - t0, usd_max: a.usd_max })
    salida.tanda2.gasto_usd = Number((salida.tanda2.gasto_usd + (typeof a.usd_max === 'number' ? a.usd_max : 0)).toFixed(6))
  }
  salida.tanda2.hecho = salida.tanda2.llamadas.length > 0 && salida.tanda2.llamadas.every((l) => l.hecho)
  salida.ampliacion = { ...(e.ampliacion || {}), gasto_usd: Number((((e.ampliacion && e.ampliacion.gasto_usd) || 0) + salida.tanda2.gasto_usd).toFixed(6)) }
  salidas.push({ json: salida })
}
return salidas

// ④ bis · RECONCILIA el puente a la biblioteca por pasadas de ≤ 40 trozos hasta que no quede nada (idempotente). Con dry_run solo cuenta (una llamada).
// Una falla se DICE; nunca se lee como «no queda nada». No llama a Apify ni a ningún modelo.
const ORIGEN = 'https://zero-risk-platform.vercel.app'
const http = async (o) => this.helpers.httpRequest({ json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 130000, ...o }).catch((err) => ({ statusCode: 0, body: { error: 'sin respuesta: ' + String((err && err.message) || err).slice(0, 140) } }))
const T0 = Date.now() // presupuesto de tiempo: n8n corta la tarea de código a los 120 s
const RESTA_MS = () => Math.max(5000, 112000 - (Date.now() - T0))
const previos = $('② ter Leer reseñas y videos (Servicio de Apify)').all().map((i) => i.json)
const alimentadas = $input.all().map((i) => { const r = i.json || {}; return r.body ? r.body : r })
const salidas = []
for (let k = 0; k < previos.length; k++) {
  const e = previos[k]
  const a = alimentadas[k] || {}
  const salida = { ...e, alimentada: a, puente_final: null }
  if (e.falla || !e.cliente || a.apagado) { salidas.push({ json: salida }); continue }
  let p = a.puente || null
  const vueltas = []
  for (let v = 0; v < 12 && Date.now() - T0 < 80000 && p && typeof p.quedan === 'number' && p.quedan > 0 && e.dry_run !== true; v++) {
    const r = await http({ timeout: RESTA_MS(), url: ORIGEN + '/api/brain/alimentar/puente', method: 'POST', headers: { 'Content-Type': 'application/json', 'x-api-key': $env.INTERNAL_API_KEY },
      body: { client_id: e.cliente, dry_run: false, workflow_id: e.workflow_id, workflow_execution_id: e.workflow_execution_id } })
    const b = r.body && typeof r.body === 'object' ? r.body : {}
    vueltas.push({ http: r.statusCode, quedan: b.puente && b.puente.quedan, errores: b.errores || [] })
    if (r.statusCode !== 200 || !b.puente) { p = { ...(p || {}), falla: 'el puente respondió ' + r.statusCode }; break }
    p = b.puente
  }
  salida.puente_final = p ? { ...p, vueltas } : null
  salidas.push({ json: salida })
}
return salidas

// ② LA AMPLIACIÓN (paso 1, lo que el flujo de la mañana NO cubre) · ejecuta SOLO lo que la ruta `plan` dejó en `acciones` de CADA cliente (ya recortado al tope de US$ 1,00 por cliente y día).
// 🔴 Con `dry_run` NO llama a nadie. 🔴 Una llamada al Servicio por acción, SIN reintento (cada una paga). 🔴 Dos fallas seguidas por cliente ⇒ para a ese cliente. Este nodo NO lee ninguna tabla: lo decide la ruta.
// El Servicio guarda lo crudo en `apify_raw` (destino `respuesta`); lo que cuesta se mide con la API de Apify y se informa a `correr`, que lo compara con el tope.
// Procesa TODOS los elementos (uno por cliente), en orden, y devuelve uno por cliente.
const N8N = 'https://n8n-production-72be.up.railway.app'
const http = async (o) => this.helpers.httpRequest({ json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 140000, ...o }).catch((err) => ({ statusCode: 0, body: { error: 'sin respuesta: ' + String((err && err.message) || err).slice(0, 140) } }))
const T0 = Date.now() // presupuesto de tiempo: n8n corta la tarea de código a los 120 s
const RESTA_MS = () => Math.max(5000, 112000 - (Date.now() - T0))
const ES_ULTIMA = false
const salidas = []
for (const item of $input.all()) {
  const e = item.json
  const salida = { ...e, ampliacion: e.ampliacion ? { ...e.ampliacion } : { hecho: false, llamadas: [], gasto_usd: 0, parado: null } }
  delete salida.acciones_pendientes
  if (e.falla || !e.cliente) { salidas.push({ json: salida }); continue }
  if (e.dry_run === true) { salida.ampliacion.nota = 'dry_run: no se llamó a ningún proveedor'; salidas.push({ json: salida }); continue }
  let seguidasConFalla = e.ampliacion && e.ampliacion.seguidas_con_falla ? e.ampliacion.seguidas_con_falla : 0
  const pendientes = []
  const lista = Array.isArray(e.acciones_pendientes) ? e.acciones_pendientes : e.acciones || []
  for (const a of lista) {
    if (salida.ampliacion.parado) continue // dos fallas seguidas: se declara en parado, no se sigue
    if (Date.now() - T0 > 60000) { pendientes.push(a); continue } // no cupo en este nodo: pasa al siguiente
    const t0 = Date.now()
    const r = await http({ timeout: RESTA_MS(), url: N8N + '/webhook/apify-service-workflow', method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: { client_id: e.cliente, apify_function: a.funcion, params: a.params, destination: 'respuesta', dry_run: false, origen: 'portero', metadata: { ...(a.metadata || {}), calling_workflow_id: e.workflow_id } } })
    const b = r.body && typeof r.body === 'object' ? r.body : {}
    const ll = { fuente: a.fuente, funcion: a.funcion, hecho: r.statusCode === 200 && b.ok === true, http: r.statusCode, ms: Date.now() - t0, apify_run_id: b.apify_run_id || null, usd_max: a.usd_max, medido: a.medido }
    if (!ll.hecho) ll.error = String(b.error || b.message || b.validation_errors || '').slice(0, 160)
    let costo = typeof a.usd_max === 'number' ? a.usd_max : 0 // sin dato real, se cuenta el MÁXIMO (nunca 0 para decir «no sé»)
    if (ll.apify_run_id && $env.APIFY_API_TOKEN) {
      const u = await http({ timeout: Math.min(15000, RESTA_MS()), url: 'https://api.apify.com/v2/actor-runs/' + ll.apify_run_id, method: 'GET', headers: { Authorization: 'Bearer ' + $env.APIFY_API_TOKEN } })
      const d = u.body && u.body.data
      if (d && d.usageTotalUsd !== undefined) { ll.costo_real_usd = Number(d.usageTotalUsd); costo = ll.costo_real_usd }
    }
    ll.costo_contado_usd = costo
    salida.ampliacion.gasto_usd = Number((salida.ampliacion.gasto_usd + costo).toFixed(6))
    salida.ampliacion.llamadas.push(ll)
    seguidasConFalla = ll.hecho ? 0 : seguidasConFalla + 1
    if (seguidasConFalla >= 2) { salida.ampliacion.parado = 'dos_fallas_seguidas'; break }
  }
  salida.ampliacion.seguidas_con_falla = seguidasConFalla
  if (ES_ULTIMA) {
    salida.ampliacion.omitidas_por_tiempo = pendientes.map((a) => a.fuente + ': ' + a.funcion) // se DICE lo que no cupo
    delete salida.ampliacion.seguidas_con_falla
  } else salida.acciones_pendientes = pendientes
  salida.ampliacion.hecho = salida.ampliacion.llamadas.length > 0 && salida.ampliacion.llamadas.every((l) => l.hecho) && pendientes.length === 0
  salidas.push({ json: salida })
}
return salidas

