// ① REPARTIR · en la ejecución del HORARIO cada cliente se corre en SU PROPIA ejecución (webhook «un cliente», llave interna). El límite de 120 s por nodo es por ejecución:
// así ninguna fuente de un cliente se recorta por el tiempo de otro. En cualquier otra entrada (a mano, despertar, un cliente) los elementos pasan SIN cambio.
// Si el plan falló o no hay clientes, pasa sin cambio (el cierre y el vigilante de ESTA ejecución lo dicen). Un reparto que falla NO pierde al cliente: se corre aquí mismo.
const N8N = 'https://n8n-production-72be.up.railway.app'
const T0 = Date.now()
const entrada = $('⓪ Entrada').first().json
const items = $input.all()
if (!entrada || entrada.via !== 'horario' || entrada.dry_run === true) return items
const clientes = items.filter((i) => i.json && i.json.cliente && !i.json.falla)
if (!clientes.length || clientes.length !== items.length) return items
const fallidos = []
const repartidos = []
for (let k = 0; k < clientes.length; k++) {
  const it = clientes[k]
  if (k > 0 && Date.now() - T0 < 90000) await new Promise((r) => setTimeout(r, 1000))
  try {
    const r = await this.helpers.httpRequest({ url: N8N + '/webhook/zero-risk/cerebro-diario-un-cliente', method: 'POST', json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000, headers: { 'Content-Type': 'application/json', 'x-api-key': $env.INTERNAL_API_KEY }, body: { client_id: it.json.cliente, origen_del_reparto: String(entrada.workflow_execution_id) } })
    if (r.statusCode === 200) repartidos.push(it.json.cliente)
    else fallidos.push(it)
  } catch (err) { fallidos.push(it) }
}
return fallidos

// ⑦ REINTENTO (la misma mañana) · si en la corrida de este cliente algo quedó omitido por tiempo, se pide UNA vez más (reintento:true ⇒ `forzar`): nunca más de una, nunca si el vigilante habló,
// nunca en una entrada a mano o en seco. Lo omitido hoy debe quedar en 0 en el caso normal; esto es la red.
const N8N = 'https://n8n-production-72be.up.railway.app'
const e = $('⓪ Entrada').first().json
const v = $input.first().json || {}
const vb = v.body ? v.body : v
const cierre = $('⑤ Cierre').first().json
const con = ((cierre && cierre.clientes) || []).filter((c) => c.cliente && Array.isArray(c.omitidas_por_tiempo) && c.omitidas_por_tiempo.length > 0)
const motivo = e.reintento === true ? 'ya es un reintento' : e.dry_run !== false ? 'en seco' : vb.ok === false ? 'el vigilante habló' : !['horario', 'cliente'].includes(e.via) ? 'entrada a mano o despertar' : !con.length ? 'nada omitido' : null
if (motivo) return [{ json: { reintento: false, motivo } }]
await new Promise((r) => setTimeout(r, 20000))
const lanzados = []
for (const c of con) {
  try {
    const r = await this.helpers.httpRequest({ url: N8N + '/webhook/zero-risk/cerebro-diario-un-cliente', method: 'POST', json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000, headers: { 'Content-Type': 'application/json', 'x-api-key': $env.INTERNAL_API_KEY }, body: { client_id: c.cliente, reintento: true } })
    lanzados.push({ cliente: c.cliente, http: r.statusCode, omitidas: c.omitidas_por_tiempo })
  } catch (err) { lanzados.push({ cliente: c.cliente, http: 0, error: String((err && err.message) || err).slice(0, 120) }) }
}
return [{ json: { reintento: true, lanzados } }]

// ⓪ ENTRADA · mantenimiento diario del portero · CC#2 · 2026-10-10 · + «completar despertar» (CC-CEREBRO · 15-oct).
//  · por HORARIO: corre de verdad (dry_run=false), para todos los clientes activos.
//  · a mano (webhook con llave de despacho): `dry_run` BOOLEANO OBLIGATORIO; `client_id` (uuid) opcional limita el alcance.
//  · completar despertar (webhook con llave interna): lo llama el ALTA para UN cliente tras el despertar; exige `client_id` uuid y `pedir_ahora === true`. Misma cadena que la diaria.
// 🔴 Sin llave, o sin `dry_run` booleano en la entrada a mano, el flujo SE DETIENE aquí: no se lee ni se escribe nada.
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
let d = null
try { d = $('Webhook · completar despertar (llave interna)').first() } catch (e) { d = null }
let w = null
try { w = $('Webhook · a mano (con llave)').first() } catch (e) { w = null }
let u = null
try { u = $('Webhook · un cliente (llave interna)').first() } catch (e) { u = null }
const base = { workflow_id: String($workflow.id), workflow_execution_id: String($execution.id) }
if (u) {
  const h = u.json || {}
  const esperada = String($env.INTERNAL_API_KEY || '')
  const recibida = String((h.headers || {})['x-api-key'] || '')
  if (!esperada || recibida !== esperada) throw new Error('UN_CLIENTE_SIN_LLAVE · falta o no coincide x-api-key · se DETIENE')
  const b = h.body || {}
  if (typeof b.client_id !== 'string' || !UUID.test(b.client_id)) throw new Error('UN_CLIENTE_INVALIDO · `client_id` es obligatorio y debe ser un uuid · se DETIENE')
  return [{ json: { ...base, via: 'cliente', dry_run: false, client_id: b.client_id, reintento: b.reintento === true } }]
}
if (d) {
  const h = d.json || {}
  const esperada = String($env.INTERNAL_API_KEY || '')
  const recibida = String((h.headers || {})['x-api-key'] || '')
  if (!esperada || recibida !== esperada) throw new Error('DESPERTAR_SIN_LLAVE · falta o no coincide x-api-key (o INTERNAL_API_KEY no está configurada) · se DETIENE')
  const b = h.body || {}
  if (typeof b.client_id !== 'string' || !UUID.test(b.client_id)) throw new Error('DESPERTAR_CLIENTE_INVALIDO · `client_id` es obligatorio y debe ser un uuid · se DETIENE')
  if (b.pedir_ahora !== true) return []
  return [{ json: { ...base, via: 'despertar', dry_run: false, client_id: b.client_id } }]
}
if (!w) return [{ json: { ...base, via: 'horario', dry_run: false, client_id: null } }]
const h = w.json || {}
const esperada = String($env.SALA_DISPATCH_KEY || '')
const recibida = String((h.headers || {})['x-sala-dispatch-key'] || '')
if (!esperada || recibida !== esperada) throw new Error('DIARIO_SIN_LLAVE · falta o no coincide x-sala-dispatch-key (o SALA_DISPATCH_KEY no está configurada) · se DETIENE')
const b = h.body || {}
if (typeof b.dry_run !== 'boolean') throw new Error('DIARIO_DRY_RUN_OBLIGATORIO · `dry_run` es obligatorio y debe ser true o false · se DETIENE')
if (b.client_id !== undefined && (typeof b.client_id !== 'string' || !UUID.test(b.client_id))) throw new Error('DIARIO_CLIENTE_INVALIDO · `client_id` debe ser un uuid · se DETIENE')
return [{ json: { ...base, via: 'a mano', dry_run: b.dry_run, client_id: b.client_id || null } }]

// ① SEPARAR EL PLAN EN UN ELEMENTO POR CLIENTE. Si el plan falló, se DICE (un fallo nunca se lee como «no hay clientes»).
const e = $('⓪ Entrada').first().json
const r = $input.first().json || {}
const p = r.body ? r.body : r
if (!p || p.error || !Array.isArray(p.clientes)) return [{ json: { ...e, cliente: null, falla: 'El plan falló: ' + String((p && (p.error || p.detalle)) || 'sin respuesta') + ' ' + String((p && p.detalle) || '') } }]
if (!p.clientes.length) return [{ json: { ...e, cliente: null, falla: null, sin_clientes: true, excluidos: p.excluidos || [] } }]
return p.clientes.map((c) => ({ json: { ...e, cliente: c.client_id, nombre: c.nombre, acciones: (c.plan && c.plan.hacer) || [], omitidas: (c.plan && c.plan.omitidas) || [], no_cubiertas: (c.plan && c.plan.no_cubiertas) || [], gastado_hoy_usd: c.gastado_hoy_usd, falla: null } }))

